item.content:encoded:
/* head COMB-598 Homepage */
/* Responsive rules without a block-attribute equivalent (@mobile/@tablet cannot change layout, grid columns or hide elements). */
@media (width <= 30rem) {
	.trending .trending-grid {
		grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
	}
	.trending .trending-card img {
		aspect-ratio: 1 !important;
	}
	/* Mobile wraps "Pro Performance / Front Splint Boots" differently from desktop. */
	.trending .trending-card:nth-child(4) > h3 br {
		display: none;
	}
	.certified .wp-block-media-text__content {
		padding: 1.6875rem 1.5rem 3.1875rem !important;
	}
	.certified .wp-block-media-text__media {
		height: 291px !important;
		min-height: 0 !important;
	}
	.certified .wp-block-media-text__media::after,
	.certified-carousel .pc-carousel__control,
	.certified .wp-block-media-text__content > p br {
		display: none;
	}
	.certified .wp-block-media-text__content > p:first-child::after {
		width: 48px;
		margin-top: 8px;
	}
	.certified .wp-block-buttons {
		flex-direction: column;
		align-items: stretch;
	}
	.certified .wp-block-button {
		width: 100%;
	}
	/* Mobile indicators sit at the left and are narrower. */
	.certified-carousel .wp-block-profchoice-carousel-indicators {
		justify-content: flex-start;
	}
	/* On the indicators, so it wins over the block's Default width. */
	.certified-carousel .pc-carousel-indicator {
		--pc-carousel-indicator-default-width: 8px;
	}
	/* 50th anniversary logo: a 174px-high band, as in the mobile design. */
	.homepage-anniversary .wp-block-image img {
		width: 100%;
		height: 174px;
		object-fit: cover;
	}
	/* The desktop line break does not apply; the underline spans the column. */
	.homepage-anniversary h2 {
		display: block;
	}
	.homepage-anniversary h2 br {
		display: none;
	}
	.homepage-anniversary h2::after {
		width: 100%;
	}
	.insider .insider-row {
		flex-direction: column;
		align-items: stretch;
	}
	.insider .insider-copy {
		flex-basis: auto !important;
	}
	.insider .insider-copy p {
		opacity: 0.82;
	}
}
/* Tablet and small desktop: the desktop layout is too tight below 1152px (wider than the @tablet state). */
@media (30rem < width <= 72rem) {
	.homepage-anniversary {
		padding: 3rem 2rem !important;
	}
	.homepage-anniversary .wp-block-image img {
		width: auto;
		max-height: 280px;
	}
	.certified .wp-block-media-text__content {
		padding-left: 7.5rem !important;
	}
	.certified .wp-block-media-text__content h2 {
		font-size: 2.75rem !important;
	}
	.certified .wp-block-media-text__content > p br {
		display: none;
	}
	.insider .insider-copy {
		flex: 1 1 50% !important;
	}
	.insider form {
		flex: 1 1 50%;
	}
}
/* Tablet (481–782px): stack like mobile. */
@media (30rem < width <= 48.875rem) {
	.trending .trending-grid {
		grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
	}
	.trending .trending-card:nth-child(4) > h3 br {
		display: none;
	}
	.certified.wp-block-media-text {
		grid-template-columns: 100% !important;
	}
	.certified .wp-block-media-text__media {
		grid-column: 1 !important;
		grid-row: 1 !important;
		height: 360px !important;
		min-height: 0 !important;
	}
	.certified .wp-block-media-text__content {
		grid-column: 1 !important;
		grid-row: 2 !important;
		padding: 2.5rem 2rem 7.375rem !important;
	}
	.certified .wp-block-media-text__media::after,
	.certified-carousel .pc-carousel__control {
		display: none;
	}
	.insider .insider-row {
		flex-direction: column;
		align-items: stretch;
	}
	.insider .insider-copy {
		flex-basis: auto !important;
	}
}
/* tail COMB-598 Homepage */

/* head COMB-593 PDP */
/* PDP page (page-id 678): edge to edge, no page title, like the Homepage. */
.page-id-678 .cbv-content {
	padding-block: 0;
}
.page-id-678 .cbv-entry__title {
	display: none;
}
.page-id-678 .cbv-content .alignfull:first-child {
	margin-block-start: 0;
}
/* Hover and focus motion, as the HTML reference (the static state is unchanged). */
.pdp :where(a, button):focus-visible {
	outline: 2px solid #14161a;
	outline-offset: 2px;
}
.pdp-breadcrumb .wp-block-breadcrumbs a {
	text-decoration: underline;
	text-decoration-color: transparent;
	text-underline-offset: 0.3em;
	transition: color 0.2s ease, text-decoration-color 0.2s ease;
}
.pdp-breadcrumb .wp-block-breadcrumbs a:is(:hover, :focus-visible) {
	color: #14161a;
	text-decoration-color: currentColor;
}
.pdp-main :is(.pdp-main__reviews, .pdp-option__guide) a {
	transition: color 0.2s ease, text-decoration-color 0.2s ease;
}
/* Underlined links (284 reviews, Size Guide): the underline goes away on hover. */
.pdp-main :is(.pdp-main__reviews, .pdp-option__guide) a:is(:hover, :focus-visible) {
	color: #14161a;
	text-decoration-color: transparent;
}
.pdp :is(.pdp-main__fav, .pdp-card__fav) .pc-inline-icon {
	transition: color 0.2s ease, transform 0.2s ease;
}
.pdp :is(.pdp-main__fav, .pdp-card__fav) .wp-block-button__link:is(:hover, :focus-visible) .pc-inline-icon {
	color: #b71c1c;
	transform: scale(1.12);
}
.pdp-main .pdp-main__thumbs > figure {
	position: relative;
	overflow: hidden;
}
.pdp-main .pdp-main__thumbs img {
	transition: transform 0.3s ease;
}
.pdp-main .pdp-main__thumbs > figure:not(.active)::after {
	content: "";
	position: absolute;
	inset: 0;
	box-shadow: inset 0 0 0 1px transparent;
	transition: box-shadow 0.2s ease;
	pointer-events: none;
}
.pdp-main .pdp-main__thumbs > figure:not(.active):hover::after {
	box-shadow: inset 0 0 0 1px #8c8f96;
}
.pdp-main .pdp-main__thumbs > figure:hover img {
	transform: scale(1.05);
}
.pdp-main :is(.pdp-rider__image, .pdp-rider__image--mobile) {
	overflow: hidden;
}
.pdp-main :is(.pdp-rider__image, .pdp-rider__image--mobile) img {
	transition: transform 0.6s ease;
}
.pdp-main .pdp-rider:hover :is(.pdp-rider__image, .pdp-rider__image--mobile) img {
	transform: scale(1.04);
}
.pdp-main .pdp-rider__link .pc-inline-icon {
	transition: transform 0.25s ease;
}
.pdp-main .pdp-rider__link .wp-block-button__link:is(:hover, :focus-visible) .pc-inline-icon {
	transform: translateX(0.35em);
}
.pdp-main .pdp-option__swatches > div {
	transition: transform 0.2s ease;
}
.pdp-main .pdp-option__swatches > div:hover {
	transform: scale(1.1);
}
.pdp-main .pdp-size {
	transition: border-color 0.2s ease;
}
.pdp-main .pdp-size:not(:first-child, :nth-child(3)):hover {
	border-color: #14161a !important;
}
.pdp-main .pdp-qty__step {
	transition: color 0.2s ease;
}
.pdp-main .pdp-qty__step:hover {
	color: #b71c1c !important;
}
.pdp-related .pdp-card__media img {
	transition: transform 0.6s ease;
}
.pdp-related .pdp-card:hover .pdp-card__media img {
	transform: scale(1.04);
}
.pdp-related .pdp-card__name a {
	text-decoration: underline;
	text-decoration-color: transparent;
	text-underline-offset: 0.2em;
	transition: text-decoration-color 0.2s ease;
}
.pdp-related .pdp-card:hover .pdp-card__name a,
.pdp-related .pdp-card__name a:focus-visible {
	text-decoration-color: currentColor;
}
.pdp-related .pdp-related__all a {
	transition: text-decoration-color 0.2s ease;
}
/* View All: the underline goes away on hover, like 284 reviews and Size Guide. */
.pdp-related .pdp-related__all a:is(:hover, :focus-visible) {
	text-decoration-color: transparent;
}
.pdp-related .pdp-card__quick {
	transform: translateY(0.5rem);
	transition: opacity 0.2s ease, transform 0.25s ease;
}
.pdp-related .pdp-card:is(:hover, :focus-within) .pdp-card__quick {
	opacity: 1;
	transform: none;
}
@media (prefers-reduced-motion: reduce) {
	.pdp-breadcrumb .wp-block-breadcrumbs a,
	.pdp-main :is(.pdp-main__reviews, .pdp-option__guide) a,
	.pdp :is(.pdp-main__fav, .pdp-card__fav) .pc-inline-icon,
	.pdp-main .pdp-main__thumbs img,
	.pdp-main .pdp-main__thumbs > figure::after,
	.pdp-main :is(.pdp-rider__image, .pdp-rider__image--mobile) img,
	.pdp-main .pdp-rider__link .pc-inline-icon,
	.pdp-main .pdp-option__swatches > div,
	.pdp-main .pdp-size,
	.pdp-main .pdp-qty__step,
	.pdp-related .pdp-card__media img,
	.pdp-related .pdp-card__name a,
	.pdp-related .pdp-related__all a,
	.pdp-related .pdp-card__quick {
		transition: none;
	}
	.pdp :is(.pdp-main__fav, .pdp-card__fav) .wp-block-button__link:is(:hover, :focus-visible) .pc-inline-icon,
	.pdp-main .pdp-main__thumbs > figure:hover img,
	.pdp-main .pdp-rider:hover :is(.pdp-rider__image, .pdp-rider__image--mobile) img,
	.pdp-main .pdp-rider__link .wp-block-button__link:is(:hover, :focus-visible) .pc-inline-icon,
	.pdp-main .pdp-option__swatches > div:hover,
	.pdp-related .pdp-card:hover .pdp-card__media img,
	.pdp-related .pdp-card__quick {
		transform: none;
	}
}
/* Thumbnails shrink together, keeping their proportion, when the column is
   narrower than four of them (as the reference). */
.pdp-main .pdp-main__thumbs > figure {
	flex: 0 1 5rem;
	min-width: 0;
	aspect-ratio: 5 / 6;
}
.pdp-main .pdp-main__thumbs--mobile > figure {
	flex-basis: 4rem;
	aspect-ratio: 64 / 76;
}
.pdp-main .pdp-main__thumbs img {
	width: 100% !important;
	height: 100% !important;
}
/* Tablet: one column with desktop type (as the reference's 30rem–48.875rem range). */
@media (30rem < width <= 48.875rem) {
	.pdp-breadcrumb {
		padding: 1rem 1.5rem !important;
	}
	.pdp-main {
		padding: 1rem 1.5rem 3rem !important;
	}
	.pdp-main .pdp-main__layout {
		flex-direction: column;
		align-items: stretch;
		gap: 1.5rem;
	}
	.pdp-main .pdp-main__stage {
		aspect-ratio: 1;
	}
	.pdp-related {
		padding: 1.25rem 1.5rem 3rem !important;
	}
	.pdp-related .pdp-related__list {
		flex-wrap: wrap;
		gap: 1.5rem 1rem;
	}
	.pdp-related .pdp-card {
		flex: 1 1 calc(50% - 0.5rem);
	}
}
/* Narrow desktop: the card's photo keeps 40% instead of a fixed text column. */
@media (48.875rem < width <= 72rem) {
	.pdp-main .pdp-rider__image {
		flex: 0 0 40%;
	}
	.pdp-main .pdp-rider__body {
		flex: 1;
		width: auto;
	}
}
/* Responsive rules without a block-attribute equivalent (font family per breakpoint, gaps, layout). */
@media (width <= 30rem) {
	/* Breadcrumb */
	.pdp-breadcrumb .wp-block-breadcrumbs.has-dm-sans-font-family {
		font-family: var(--wp--preset--font-family--montserrat) !important;
	}
	.pdp-breadcrumb .wp-block-breadcrumbs ol {
		gap: 0.25rem;
	}
	.pdp-breadcrumb .wp-block-breadcrumbs li {
		gap: 0.25rem;
	}
	.pdp-breadcrumb .wp-block-breadcrumbs li + li::before {
		font-family: var(--wp--preset--font-family--dm-sans);
		font-size: 0.75rem;
	}

	/* Main: stacked; Montserrat where the mobile design uses it. */
	.pdp-main .pdp-main__layout {
		flex-direction: column;
		align-items: stretch;
	}
	.pdp-main .pdp-main__media,
	.pdp-main .pdp-main__info {
		flex: none;
	}
	.pdp-main .pdp-main__stage {
		aspect-ratio: 1;
	}
	.pdp-main .pdp-main__badge {
		top: 1rem;
		left: 1rem;
	}
	.pdp-main .pdp-main__fav--overlay .wp-block-button__link {
		width: 2.125rem !important;
		height: 2.125rem !important;
		border-radius: 1.0625rem !important;
	}
	.pdp-main .pdp-main__thumbs {
		overflow-x: auto;
	}
	/* Mobile thumbnails are their own 64x76 files (the reference's srcset). */
	.pdp-main .pdp-main__thumbs--desktop {
		display: none !important;
	}
	.pdp-main .pdp-main__thumbs--mobile {
		display: flex !important;
	}
	.pdp-main :is(.pdp-main__badge, .pdp-main__title, .pdp-main__rating, .pdp-main__reviews, .pdp-main__sku, .pdp-main__price, .pdp-main__description, .pdp-rider__eyebrow, .pdp-rider__name, .pdp-rider__link .wp-block-button__link, .pdp-qty__step, .pdp-main__cart .wp-block-button__link) {
		font-family: var(--wp--preset--font-family--montserrat) !important;
	}
	.pdp-main .pdp-option__label {
		font-family: var(--wp--preset--font-family--dm-sans) !important;
	}
	.pdp-main .pdp-main__meta {
		flex-direction: column;
		align-items: stretch;
	}
	.pdp-main .pdp-main__rating {
		flex: none;
	}
	.pdp-main .pdp-main__stars {
		min-width: 5rem;
	}
	.pdp-main .pdp-main__score {
		font-weight: 700 !important;
	}
	.pdp-main .pdp-main__price-row {
		justify-content: flex-start;
	}
	.pdp-main .pdp-main__price {
		flex: none;
	}
	.pdp-main .pdp-main__stock::before {
		width: 0.4375rem;
		height: 0.4375rem;
	}
	.pdp-main .pdp-rider {
		align-items: stretch;
		overflow: hidden;
	}
	.pdp-main .pdp-rider__image {
		display: none;
	}
	.pdp-main .pdp-rider__image--mobile {
		display: block;
		flex: none;
		width: 9.375rem;
		min-height: 7.5rem;
	}
	.pdp-main .pdp-rider__body {
		flex: 1;
		width: auto;
	}
	.pdp-main .pdp-size {
		min-width: 2.875rem;
	}
	.pdp-main .pdp-qty__step {
		width: 2.375rem;
	}
	.pdp-main .pdp-qty__value {
		width: 2rem;
	}
	.pdp-main .pdp-main__cart .wp-block-button__link {
		min-height: 0;
	}
	.pdp-main .pdp-main__fav--box .wp-block-button__link {
		height: auto !important;
		min-height: 3.25rem;
	}

	/* Related: a scrolling row of 180px cards, Montserrat type. */
	.pdp-related :is(.pdp-related__title, .pdp-related__all) {
		font-family: var(--wp--preset--font-family--montserrat) !important;
	}
	.pdp-related .pdp-related__list {
		justify-content: flex-start;
		overflow-x: auto;
	}
	.pdp-related .pdp-card {
		flex: none;
		width: 11.25rem;
	}
	.pdp-related .pdp-card__media {
		height: 13.75rem;
		aspect-ratio: auto;
	}
	.pdp-related .pdp-card__badge {
		top: 0.5rem;
		left: 0.5rem;
	}
	.pdp-related .pdp-card__fav {
		top: 0.5rem;
		right: 0.375rem;
	}
	.pdp-related .pdp-card__fav .wp-block-button__link {
		width: 1.625rem !important;
		height: 1.625rem !important;
	}
	.pdp-related .pdp-card__quick {
		display: none;
	}
	.pdp-related .pdp-card__swatch {
		width: 0.6875rem;
		height: 0.6875rem;
	}
}

@media (prefers-reduced-motion: reduce) {
	.pdp-related .pdp-card__quick {
		transition: none;
	}
}
/* tail COMB-593 PDP */

/* head TEMP */
/* Development only: hide the theme header and footer on the PDP page while it is compared with the HTML bases. Remove before delivery. */
.page-id-678 .cbv-header,
.page-id-678 .cbv-footer {
	display: none;
}
/* tail TEMP */
